import {initWorkspace} from './workspace.js';
const shapes=[['rect','▭','Rectangle','Straight or rounded corners'],['ellipse','◯','Ellipse','Circles and ovals'],['triangle','△','Triangle','Three editable points'],['polygon','⬡','Polygon','Change its number of sides'],['star','☆','Star','Change points and inner radius'],['line','╱','Line','An open two-point path']];
export const shapeTools=shapes.map(s=>s[0]);
export function shapePalette(a){return `<div class="shape-dock" role="group" aria-label="Choose a shape">${shapes.map(([tool,icon,label,note])=>`<button data-shape="${tool}" aria-pressed="${a.tool===tool}" class="${a.tool===tool?'active':''}" title="${note}"><span class="shape-icon" aria-hidden="true">${icon}</span><span>${label}</span></button>`).join('')}</div>`;}
export function chooseShape(a,tool){if(!shapeTools.includes(tool))return;a.stage.finishPath();a.tool=tool;a.nodeEdit=false;a.meshSplit=false;a.meshPlacement=null;a.meshInsert=false;a.activeNode=null;a.shapesOpen=!a.workspaceGuided;a.render();}
export function showShapes(a){initWorkspace(a);if(!a.workspaceGuided){a.shapesOpen=!a.shapesOpen;a.render();return;}a.shapesOpen=true;a.render();const d=a.dialog('Shapes',shapePalette(a)+'<p class="subtle">Choose a shape, then drag on the canvas. Double-tap empty canvas to place a standard shape.</p>');d.classList.add('shape-popup');d.querySelectorAll('[data-shape]').forEach(button=>button.onclick=()=>{chooseShape(a,button.dataset.shape);d.close();});d.addEventListener('close',()=>{a.shapesOpen=false;a.render();},{once:true});}
